package com.finance.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.LocalDate;
@Document("financialGoals") public class FinancialGoal { @Id private String id; private String userId; private String name; private long targetPaise; private long savedPaise; private LocalDate targetDate; public String getId(){return id;} public void setId(String v){id=v;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public String getName(){return name;} public void setName(String v){name=v;} public long getTargetPaise(){return targetPaise;} public void setTargetPaise(long v){targetPaise=v;} public long getSavedPaise(){return savedPaise;} public void setSavedPaise(long v){savedPaise=v;} public LocalDate getTargetDate(){return targetDate;} public void setTargetDate(LocalDate v){targetDate=v;} }
